# Generated by Phase: IMPLEMENT | Feature: EVOL-102
"""SETUP discovery as data (EVOL-102): one question registry, one answer home, one condition grammar and evaluator.

registry    `.context/templates/setup/setup/discovery_registry.json` — `questions[{id, tier, since, when?, keys}]`, a key
            spec is exactly one of `options` | `options_by {key, values}` | `free` (a closed kind), plus `record_only`
            (a reason) and, on `free: text` only, `suggestions` (the literals a condition may compare it to); top-level `derived {key: {from}}` — values earlier answers decide, never asked.
grammar     condition := conj (" OR " conj)* · conj := clause (" AND " clause)* (AND binds tighter, no parentheses) ·
            clause := KEY " exists" | KEY ("=="|"!=") VALUE | KEY (" IN "|" NOT IN ") "[" VALUE ("," VALUE)* "]" ·
            VALUE := "quoted" | null | true | false | number | bare token (spaces allowed: `Azure DevOps`).
answers     `docs/setup.md` frontmatter flattened to dotted keys (or a fixture `{"answers": {...}}`, its keys held to the
            registry). An absent or fence-less docs/setup.md is a fault. A missing key reads as null; `!=` and `NOT IN`
            hold only for a key that holds an answer (a null key never differs); `exists` holds when the key, or a key
            under it, has a value other than null, "None", "" or an empty list / dict; a list answer may only be tested
            with `exists`.
resolve     fail-closed: every `when` and `stack_conditional` held to the registry first; then the pending questions (tier order, then registry order: `when` holds, no key answered yet — null = not yet asked) and the manifest
            `templates` entries that land (no `stack_conditional`, or it holds) and those skipped.
validate    V1 schema · V2 a single option not derived · V3 a credential-named key not `free: vault_name` · V4 a key with
            no consumer and no `record_only` · V5 every condition parses and names registry keys and offered literals ·
            V6 parity with the discovery instruction · V7 parity with the setup template frontmatter · V8 the consumer
            literals (the checks of the retired test-discovery-literals.sh, read from the registry) · V9 the snapshot's
            STACK_KEYS are registry keys.
"""
from __future__ import annotations

import fnmatch
import json
import re
from pathlib import Path

from .common import FM_RE, GateFault, parse_yaml, read_frontmatter, tracked_files

REGISTRY = ".context/templates/setup/setup/discovery_registry.json"
MANIFEST = ".context/templates/setup/governance_versions.json"
INSTRUCTION = ".claude/instructions/Factory-setup-discovery.instructions.md"
MATERIALIZATION = ".claude/instructions/Factory-setup-materialization.instructions.md"
TEMPLATE = ".context/templates/setup/setup/setup_master_template.md"
SETUP_MD = "docs/setup.md"

TIERS = (0, 1, 2)
FREE_KINDS = ("text", "number", "list", "path", "command", "vault_name")
SPEC_KINDS = ("options", "options_by", "free")
NON_ANSWER_SLOTS = ("version", "date", "changelog", "phase", "status", "retry_count", "last_update")
CREDENTIAL_WORDS = {"password", "passwd", "secret", "token", "credential", "credentials", "apikey"}
CREDENTIAL_PAIRS = {("api", "key"), ("private", "key")}
CONSUMER_ROOTS = ("scripts/", ".claude/instructions/", ".claude/skills/", ".claude/commands/", ".claude/hooks/",
                  ".context/templates/", ".github/workflows/", "config/")
# never a consumer: the writers (the instruction, the registry, the template), the manifest and its changelogs, the
# tests and the answer fixtures (a mention there proves no read)
NOT_CONSUMERS = (INSTRUCTION, REGISTRY, TEMPLATE)
NOT_CONSUMER_GLOBS = ("*governance_versions.json", "*/test_*.py", "*scripts/test-*.sh", "*scripts/fixtures/*")

KEY = r"[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z0-9_]+)*"
QID = re.compile(r"^Q\d+(?:\.\d+)*[a-z]?$")
SEMVER = re.compile(r"^(\d+)\.(\d+)\.(\d+)$")


# ─── grammar ─────────────────────────────────────────────────────────────────────

def _split(text: str, sep: str) -> list[str]:
    """Split on `sep` outside double quotes and brackets."""
    out, cur, quote, depth, i = [], "", False, 0, 0
    while i < len(text):
        ch = text[i]
        if not quote and depth == 0 and text.startswith(sep, i):
            out.append(cur); cur = ""; i += len(sep); continue
        if ch == '"':
            quote = not quote
        elif not quote and ch == "[":
            depth += 1
        elif not quote and ch == "]":
            depth -= 1
        cur += ch; i += 1
    out.append(cur)
    return out


def _fault(cond: str, clause: str, why: str) -> GateFault:
    return GateFault(f"the condition `{cond}` is outside the discovery grammar: `{clause}` — {why} "
                     "(KEY exists | KEY ==/!= VALUE | KEY IN/NOT IN [VALUE, …], joined by AND / OR)")


def _value(cond: str, clause: str, raw: str):
    v = raw.strip()
    if not v:
        raise _fault(cond, clause, "a value is missing")
    if v.startswith('"'):
        if len(v) < 2 or not v.endswith('"') or '"' in v[1:-1]:
            raise _fault(cond, clause, f"`{v}` is not one quoted value")
        return v[1:-1]
    if v == "null":
        return None
    if v in ("true", "false"):
        return v == "true"
    if re.fullmatch(r"-?\d+", v):
        return int(v)
    if re.fullmatch(r"-?\d+\.\d+", v):
        return float(v)
    if re.search(r"(?:^|\s)(?:AND|OR|IN|NOT)(?:\s|$)", v):
        raise _fault(cond, clause, f"`{v}` carries a keyword — a dangling AND / OR, or a misspelt operator")
    if re.search(r'["\[\],=!<>~]', v):
        raise _fault(cond, clause, f"`{v}` is not a value (quote it, or use a bare token without quotes, brackets, commas or operators)")
    return v


def parse(cond) -> list[list[dict]]:
    """A condition → its AST: a list of conjunctions (OR), each a list of clauses (AND). GateFault when it does not parse."""
    if not isinstance(cond, str) or not cond.strip():
        raise _fault(str(cond), str(cond), "the condition is empty")
    cond = cond.strip()
    ast = []
    for conj in _split(cond, " OR "):
        clauses = []
        for raw in _split(conj, " AND "):
            c = raw.strip()
            if not c:
                raise _fault(cond, raw, "an empty clause (a dangling AND / OR)")
            m = re.fullmatch(rf"({KEY}) exists", c)
            if m:
                clauses.append({"key": m.group(1), "op": "exists"}); continue
            m = re.fullmatch(rf"({KEY}) (NOT IN|IN) \[(.*)\]", c)
            if m:
                items = [x for x in _split(m.group(3), ",")]
                if not m.group(3).strip():
                    raise _fault(cond, c, "an empty list")
                clauses.append({"key": m.group(1), "op": m.group(2), "values": [_value(cond, c, x) for x in items]}); continue
            m = re.fullmatch(rf"({KEY}) ?(==|!=) ?(.*)", c)
            if m:
                clauses.append({"key": m.group(1), "op": m.group(2), "value": _value(cond, c, m.group(3))}); continue
            raise _fault(cond, c, "not a clause")
        ast.append(clauses)
    return ast


def canon(v) -> str:
    """One comparable form: null, true/false, numbers and strings as their literal text."""
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)


def flatten(fm: dict, prefix: str = "") -> dict:
    """Nested frontmatter → {dotted key: leaf value}; a dotted key stays as it is; a list is a leaf."""
    out = {}
    for k, v in (fm or {}).items():
        dk = f"{prefix}{k}"
        if isinstance(v, dict) and v:
            out.update(flatten(v, dk + "."))
        else:
            out[dk] = v
    return out


def _has_value(v) -> bool:
    return v is not None and v != "None" and v != "" and v != [] and v != {}


def _exists(key: str, answers: dict) -> bool:
    return any(_has_value(v) for k, v in answers.items() if k == key or k.startswith(key + "."))


def _clause(c: dict, answers: dict) -> bool:
    if c["op"] == "exists":
        return _exists(c["key"], answers)
    v = answers.get(c["key"])
    if isinstance(v, (list, dict)):
        raise GateFault(f"`{c['key']}` holds a list; a list answer may only be tested with `exists`")
    if c["op"] in ("!=", "NOT IN") and v is None:
        return False   # a null key never differs: `!=` / `NOT IN` hold only for a key that holds an answer
    if c["op"] in ("==", "!="):
        same = canon(v) == canon(c["value"])
        return same if c["op"] == "==" else not same
    inside = canon(v) in {canon(x) for x in c["values"]}
    return inside if c["op"] == "IN" else not inside


def evaluate(ast: list[list[dict]], answers: dict) -> bool:
    return any(all(_clause(c, answers) for c in conj) for conj in ast)


# ─── registry ────────────────────────────────────────────────────────────────────

def load_registry(repo: Path) -> dict:
    p = repo / REGISTRY
    if not p.is_file():
        raise GateFault(f"the discovery registry {REGISTRY} is absent — the questions SETUP asks, their options and their conditions live there (EVOL-102); write it, then re-run")
    try:
        reg = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"the discovery registry {REGISTRY} is not readable JSON ({e})") from None
    if not isinstance(reg, dict) or not isinstance(reg.get("questions"), list):
        raise GateFault(f"the discovery registry {REGISTRY} carries no `questions` list")
    return reg


def _questions(reg: dict) -> list[dict]:
    return [q for q in reg.get("questions", []) if isinstance(q, dict)]


def _specs(reg: dict) -> dict:
    """{key: spec} over every question (first declaration wins; V1 reports duplicates)."""
    out = {}
    for q in _questions(reg):
        for k, s in (q.get("keys") or {}).items() if isinstance(q.get("keys"), dict) else []:
            out.setdefault(k, s if isinstance(s, dict) else {})
    return out


def _derived(reg: dict) -> dict:
    d = reg.get("derived")
    return d if isinstance(d, dict) else {}


def _offered(spec: dict) -> list[str] | None:
    """The closed literals of a key (canonical text), or None for a free key."""
    if isinstance(spec.get("options"), list):
        return sorted({canon(x) for x in spec["options"]})
    ob = spec.get("options_by")
    if isinstance(ob, dict) and isinstance(ob.get("values"), dict):
        return sorted({canon(x) for vals in ob["values"].values() if isinstance(vals, list) for x in vals})
    return None


def load_manifest(repo: Path) -> dict:
    p = repo / MANIFEST
    try:
        m = json.loads(p.read_text(encoding="utf-8"))
    except FileNotFoundError:
        raise GateFault(f"the governance manifest {MANIFEST} is absent — the template entries and their conditions live there") from None
    except (OSError, ValueError) as e:
        raise GateFault(f"the governance manifest {MANIFEST} is not readable JSON ({e})") from None
    return m if isinstance(m, dict) else {}


def check(ast: list[list[dict]], reg: dict) -> list[str]:
    """What a condition names that the registry does not hold: an unknown key, a prefix compared, a list compared, a
    literal outside the key's options."""
    specs, derived = _specs(reg), _derived(reg)
    known = set(specs) | set(derived)
    out = []
    for conj in ast:
        for c in conj:
            k = c["key"]
            if k not in known:
                if any(x.startswith(k + ".") for x in known):
                    if c["op"] != "exists":
                        out.append(f"`{k}` is a prefix of registry keys — a prefix may only be tested with `exists`")
                else:
                    out.append(f"`{k}` is not a registry or derived key")
                continue
            spec = specs.get(k, {})
            if c["op"] == "exists":
                continue
            if spec.get("free") == "list":
                out.append(f"`{k}` is a list answer — it may only be tested with `exists`")
                continue
            if k in derived:
                continue   # a derived key: computed, no list to hold a literal to
            offered = _offered(spec)
            if offered is None:   # free text: only its suggestions (or null) — a literal nobody offers is drift
                offered = sorted({canon(x) for x in spec.get("suggestions") or [] if isinstance(spec.get("suggestions"), list)})
            for lit in ([c["value"]] if "value" in c else c["values"]):
                if lit is not None and canon(lit) not in offered:
                    out.append(f"`{canon(lit)}` is not offered for `{k}` ({' | '.join(offered) or 'free text without suggestions: compare it only to null'})")
    return out


# ─── answers + resolve + eval ────────────────────────────────────────────────────

def answers(repo: Path, file: Path | None = None) -> dict:
    """The answer set: a fixture file `{"answers": {...}}`, else the docs/setup.md frontmatter; flattened."""
    if file is not None:
        try:
            doc = json.loads(Path(file).read_text(encoding="utf-8"))
        except (OSError, ValueError) as e:
            raise GateFault(f"the answers file {file} is not readable JSON ({e})") from None
        if not isinstance(doc, dict) or not isinstance(doc.get("answers"), dict):
            raise GateFault(f"the answers file {file} carries no `answers` object ({{\"answers\": {{\"<dotted key>\": value}}}})")
        ans = flatten(doc["answers"])
        reg = load_registry(repo)
        known = set(_specs(reg)) | set(_derived(reg))
        unknown = [k for k in ans if not any(k == r or k.startswith(r + ".") for r in known)]
        if unknown:
            raise GateFault(f"the answers file {file} answers {', '.join(f'`{k}`' for k in unknown)} — not a registry or derived key "
                            f"(a typo, or a question the registry {REGISTRY} does not ask)")
        return ans
    p = repo / SETUP_MD
    if not p.is_file():
        raise GateFault(f"the answer home {SETUP_MD} is absent — SETUP creates it at the start of discovery; run SETUP, or pass --answers FILE")
    text = p.read_text(encoding="utf-8", errors="replace")
    m = FM_RE.match(text)
    if not m:
        raise GateFault(f"the answer home {SETUP_MD} has no readable frontmatter (a `---` fence at the top, YAML inside) — the answers live there")
    data = parse_yaml(m.group(1))
    if not isinstance(data, dict):
        raise GateFault(f"the answer home {SETUP_MD} frontmatter is not a mapping — the answers live there as `key: value` lines")
    return flatten(data)


def _answered(key: str, ans: dict) -> bool:
    return any(v is not None for k, v in ans.items() if k == key or k.startswith(key + "."))


def resolve(repo: Path, ans: dict) -> dict:
    reg = load_registry(repo)
    manifest = load_manifest(repo)
    templates = manifest.get("templates")
    if not isinstance(templates, dict) or not templates:
        raise GateFault(f"the governance manifest {MANIFEST} carries no `templates` entries — nothing to select from")
    for where, c in _conditions(repo, reg, manifest):   # fail-closed: a condition the registry does not hold faults, never skips
        try:
            problems = check(parse(c), reg)
        except GateFault as e:
            raise GateFault(f"{where}: {e}") from None
        if problems:
            raise GateFault(f"{where}: `{c}` does not hold to the registry: " + "; ".join(problems))
    qs = sorted(enumerate(_questions(reg)), key=lambda iq: (iq[1].get("tier") if isinstance(iq[1].get("tier"), int) else 99, iq[0]))
    pending = []
    for _, q in qs:
        if q.get("when") and not evaluate(parse(q["when"]), ans):
            continue
        if not any(_answered(k, ans) for k in (q.get("keys") or {})):   # asked = some key holds an answer (null = not yet asked);
            pending.append(q.get("id"))                                 # a sibling left null on purpose (Q14 path, Q29.1 dir) is part of it
    landing, skipped = [], []
    for k, e in templates.items():
        if not isinstance(e, dict):
            continue
        c = e.get("stack_conditional")
        (landing if not c or evaluate(parse(c), ans) else skipped).append(k)
    return {"pending": pending, "landing": landing, "skipped": skipped}


def checked(repo: Path, cond: str) -> list[list[dict]]:
    """A condition parsed and held to the registry, before any answer is read; GateFault otherwise."""
    ast = parse(cond)
    problems = check(ast, load_registry(repo))
    if problems:
        raise GateFault(f"the condition `{cond}` does not hold to the registry: " + "; ".join(problems))
    return ast


def eval_condition(repo: Path, cond: str, ans: dict) -> bool:
    return evaluate(checked(repo, cond), ans)


def render_resolve(r: dict) -> str:
    lines = [f"discovery: {len(r['pending'])} pending question(s)" + (f": {', '.join(r['pending'])}" if r["pending"] else " — every question that applies is answered"),
             f"  templates landing ({len(r['landing'])}):"]
    lines += [f"    + {k}" for k in r["landing"]]
    lines.append(f"  templates skipped ({len(r['skipped'])}):")
    lines += [f"    - {k}" for k in r["skipped"]]
    return "\n".join(lines)


# ─── validator ───────────────────────────────────────────────────────────────────

def _semver(v) -> tuple | None:
    m = SEMVER.match(str(v or ""))
    return tuple(int(x) for x in m.groups()) if m else None


def _v1(reg: dict, fw: tuple | None) -> list[str]:
    out, ids, keys = [], {}, {}
    for top in reg:
        if top not in ("questions", "derived") and not top.startswith(("_", "$")):
            out.append(f"V1 · top-level `{top}` is not a registry field (questions, derived)")
    for n, q in enumerate(reg.get("questions") or []):
        if not isinstance(q, dict):
            out.append(f"V1 · question #{n + 1} is not an object"); continue
        qid = q.get("id")
        where = f"question `{qid}`" if qid else f"question #{n + 1}"
        if not isinstance(qid, str) or not QID.match(qid):
            out.append(f"V1 · {where}: id `{qid}` is not `Q<number>` (as its `#### Q…` heading)")
        elif qid in ids:
            out.append(f"V1 · `{qid}` is declared twice")
        ids.setdefault(qid, n)
        for f in q:
            if f not in ("id", "tier", "since", "when", "keys"):
                out.append(f"V1 · {where}: `{f}` is not a question field (id, tier, since, when, keys)")
        if q.get("tier") not in TIERS or isinstance(q.get("tier"), bool):
            out.append(f"V1 · {where}: tier {q.get('tier')} is not one of {', '.join(map(str, TIERS))}")
        sv = _semver(q.get("since"))
        if sv is None:
            out.append(f"V1 · {where}: since `{q.get('since')}` is not a version (x.y.z)")
        elif fw is not None and sv > fw:
            out.append(f"V1 · {where}: since {q.get('since')} is above framework_version {'.'.join(map(str, fw))}")
        if "when" in q and (not isinstance(q["when"], str) or not q["when"].strip()):
            out.append(f"V1 · {where}: `when` is not a condition")
        if not isinstance(q.get("keys"), dict) or not q["keys"]:
            out.append(f"V1 · {where}: no `keys`"); continue
        for k, s in q["keys"].items():
            if not re.fullmatch(r"[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)*", k):
                out.append(f"V1 · {where}: key `{k}` is not a dotted lower-case key")
            if k in keys:
                out.append(f"V1 · key `{k}` is declared twice ({keys[k]}, {qid})")
            keys.setdefault(k, qid)
            if not isinstance(s, dict):
                out.append(f"V1 · `{k}`: its spec is not an object"); continue
            kinds = [x for x in SPEC_KINDS if x in s]
            if len(kinds) != 1:
                out.append(f"V1 · `{k}`: a spec carries exactly one of options | options_by | free (it carries {', '.join(kinds) or 'none'})")
            for f in s:
                if f not in SPEC_KINDS + ("record_only", "suggestions"):
                    out.append(f"V1 · `{k}`: `{f}` is not a key-spec field (options, options_by, free, record_only, suggestions)")
            if "suggestions" in s and (s.get("free") != "text" or not isinstance(s["suggestions"], list) or not s["suggestions"]
                                       or len({canon(x) for x in s["suggestions"]}) != len(s["suggestions"])):
                out.append(f"V1 · `{k}`: suggestions is a non-empty list of distinct literals on a `free: text` key only")
            if "record_only" in s and (not isinstance(s["record_only"], str) or not s["record_only"].strip()):
                out.append(f"V1 · `{k}`: record_only needs its reason")
            if "options" in s and (not isinstance(s["options"], list) or not s["options"] or len({canon(x) for x in s["options"]}) != len(s["options"])):
                out.append(f"V1 · `{k}`: options is not a non-empty list of distinct literals")
            if "free" in s and s["free"] not in FREE_KINDS:
                out.append(f"V1 · `{k}`: free kind `{s['free']}` is not one of {', '.join(FREE_KINDS)}")
    specs = _specs(reg)
    for k, s in specs.items():
        ob = s.get("options_by")
        if "options_by" not in s:
            continue
        if not isinstance(ob, dict) or not isinstance(ob.get("values"), dict) or not ob.get("key"):
            out.append(f"V1 · `{k}`: options_by is {{key, values: {{<parent literal>: [...]}}}}"); continue
        parent = specs.get(ob["key"])
        offered = _offered(parent) if parent and "options" in parent else None
        if offered is None:
            out.append(f"V1 · `{k}`: options_by names `{ob['key']}`, which is not a registry key with options"); continue
        for lit, vals in ob["values"].items():
            if lit not in offered:
                out.append(f"V1 · `{k}`: options_by literal `{lit}` is not one of `{ob['key']}`'s options ({' | '.join(offered)})")
            if not isinstance(vals, list) or not vals:
                out.append(f"V1 · `{k}`: options_by `{lit}` is not a non-empty list")
    d = reg.get("derived", {})
    if not isinstance(d, dict):
        out.append("V1 · `derived` is not an object")
    else:
        for k, s in d.items():
            if k in specs:
                out.append(f"V1 · `{k}` is both asked and derived")
            if not isinstance(s, dict) or not isinstance(s.get("from"), str) or not s["from"].strip() or set(s) - {"from"}:
                out.append(f"V1 · derived `{k}`: the spec is {{from: \"<how earlier answers decide it>\"}}")
    return out


def _v2(reg: dict) -> list[str]:
    out = []
    for k, s in _specs(reg).items():
        if isinstance(s.get("options"), list) and len(s["options"]) == 1:
            out.append(f"V2 · `{k}` offers one option ({canon(s['options'][0])}) — a decided value is derived, never asked: move it to `derived`")
        ob = s.get("options_by")
        if isinstance(ob, dict) and isinstance(ob.get("values"), dict):
            for lit, vals in ob["values"].items():
                if isinstance(vals, list) and len(vals) == 1:
                    out.append(f"V2 · `{k}` offers one option when `{ob.get('key')}` is `{lit}` ({canon(vals[0])}) — derive it, never ask it")
    return out


def _credential(key: str) -> bool:
    for seg in key.split("."):
        words = seg.lower().split("_")
        if CREDENTIAL_WORDS & set(words) or any(p in CREDENTIAL_PAIRS for p in zip(words, words[1:])):
            return True
    return False


def _v3(reg: dict) -> list[str]:
    return [f"V3 · `{k}` can carry a secret — its spec must be `free: vault_name` (the vault entry's name, never the value)"
            for k, s in _specs(reg).items() if _credential(k) and s.get("free") != "vault_name"]


def _consumer_files(repo: Path) -> list[str]:
    return [f for f in tracked_files(repo)
            if f.startswith(CONSUMER_ROOTS) and f not in NOT_CONSUMERS and not any(fnmatch.fnmatch(f, g) for g in NOT_CONSUMER_GLOBS)]


def _v4(repo: Path, reg: dict) -> list[str]:
    owed = [k for k, s in _specs(reg).items() if not (isinstance(s.get("record_only"), str) and s["record_only"].strip())]
    if not owed:
        return []
    rx = re.compile(r"(?<![A-Za-z0-9_])(" + "|".join(re.escape(k) for k in sorted(owed, key=len, reverse=True)) + r")(?![A-Za-z0-9_])")
    seen = set()
    for rel in _consumer_files(repo):
        try:
            text = (repo / rel).read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        seen.update(rx.findall(text))
        # a shorter key inside a longer one (`a.b` within `a.b.c`) is found by its own scan
        for k in owed:
            if k not in seen and k in text and re.search(r"(?<![A-Za-z0-9_])" + re.escape(k) + r"(?![A-Za-z0-9_])", text):
                seen.add(k)
    return [f"V4 · `{k}` is persisted and nothing reads it (scripts, .claude instructions / skills / commands / hooks, templates, workflows, config) — add its reader or a `record_only` reason"
            for k in owed if k not in seen]


def _conditions(repo: Path, reg: dict, manifest: dict) -> list[tuple[str, str]]:
    out = [(f"registry {q.get('id')} when", q["when"]) for q in _questions(reg) if isinstance(q.get("when"), str)]
    for sect, entries in manifest.items():
        if isinstance(entries, dict):
            for k, e in entries.items():
                if isinstance(e, dict) and e.get("stack_conditional") is not None:
                    out.append((f"manifest {k}", e["stack_conditional"]))
    return out


def _v5(repo: Path, reg: dict, manifest: dict) -> list[str]:
    out = []
    conds = _conditions(repo, reg, manifest)
    p = repo / MATERIALIZATION
    if not p.is_file():
        out.append(f"V5 · {MATERIALIZATION} is absent — its `--eval` conditions cannot be checked")
    else:
        for n, line in enumerate(p.read_text(encoding="utf-8", errors="replace").splitlines(), 1):
            for m in re.finditer(r"discovery --eval(=|[ \t]+(\S)|[ \t]*$)?", line):
                if m.group(1) is None or m.group(2) == "`":
                    continue   # prose naming the flag, no condition after it
                if m.group(2) != "'":
                    out.append(f"V5 · {MATERIALIZATION}:{n}: write --eval conditions in single quotes, on the same line (a double-quoted, bare, "
                               f"`--eval=` or next-line condition is split by the shell or never checked)")
            for m in re.finditer(r"discovery --eval '([^']*)'", line):
                if not m.group(1).startswith("<"):   # a `<condition>` placeholder in usage prose is no condition
                    conds.append((f"{MATERIALIZATION}:{n}", m.group(1)))
    for where, c in conds:
        try:
            ast = parse(c)
        except GateFault as e:
            out.append(f"V5 · {where}: {e}"); continue
        out += [f"V5 · {where}: `{c}` — {p_}" for p_ in check(ast, reg)]
    return out


def _persist_keys(line: str) -> tuple[list[str], list[str], int]:
    """A `**Persist:**` line → (keys, wildcard prefixes, backticked token count). Dotted tokens anywhere; the first
    token also when it is one segment (`project_mode`); `.sub` reads under the line's first dotted key."""
    toks = re.findall(r"`([^`]+)`", line)
    keys, wild, base = [], [], None
    for i, t in enumerate(toks):
        t = t.strip()
        if re.fullmatch(r"[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)*\.\*", t):
            wild.append(t[:-2]); base = base or t[:-2]
        elif re.fullmatch(r"[a-z][a-z0-9_]*(?:\.[a-z0-9_]+)+(?:\[\])?", t) or (i == 0 and re.fullmatch(r"[a-z][a-z0-9_]*(?:\[\])?", t)):
            k = t[:-2] if t.endswith("[]") else t
            keys.append(k)
            if base is None and "." in k:
                base = k.rsplit(".", 1)[0]
        elif base and re.fullmatch(r"\.[a-z0-9_]+(?:\[\])?", t):
            keys.append(base + (t[:-2] if t.endswith("[]") else t))
    return keys, wild, len(toks)


def _instruction(repo: Path) -> dict:
    """{qid: {keys, wild, toks, options, rows}} per `#### Q…` / `##### Q…` block (the parsing of test-discovery-literals)."""
    p = repo / INSTRUCTION
    if not p.is_file():
        raise GateFault(f"the discovery instruction {INSTRUCTION} is absent — V6 holds the registry to it")
    text = p.read_text(encoding="utf-8")
    out = {}
    for blk in re.split(r"\n(?=#{4,5} Q)", text):
        h = re.match(r"#{4,5} (Q[\d.]+[a-z]?)\b", blk)
        if not h:
            continue
        per = re.search(r"^- \*\*Persist[^*]*:\*\*[ \t]*(.+)$", blk, re.M)
        keys, wild, ntok = _persist_keys(per.group(1)) if per else ([], [], 0)
        opt = re.search(r"^- \*\*Options[^*]*:\*\*[ \t]*(.*)$", blk, re.M)
        rows = re.findall(r"^- ([^*`\n→]+?) → (.+)$", blk, re.M)   # Q10: per-parent rows
        def lits(row):
            return [re.sub(r"\s*\(.*$", "", o).strip().strip("`") for o in row.split("|")]
        def literal(opts):
            return opts and not any(not o or len(o) > 30 or re.search(r"[`:*]|^-", o) for o in opts)
        options = lits(opt.group(1)) if opt and opt.group(1).strip() else None
        options = sorted(set(options)) if options and literal(options) else None
        by = {lab.strip(): sorted(set(lits(r))) for lab, r in rows} if not opt and rows else None
        if by and not all(literal(v) for v in by.values()):
            by = None
        out[h.group(1)] = {"keys": keys, "wild": wild, "toks": ntok, "persist": bool(per), "options": options, "rows": by}
    return out


def _v6(repo: Path, reg: dict) -> list[str]:
    inst = _instruction(repo)
    out = []
    for q in _questions(reg):
        qid, qkeys = q.get("id"), list((q.get("keys") or {}).keys())
        if qid not in inst:
            out.append(f"V6 · registry question {qid} has no `#### {qid}` heading in the discovery instruction"); continue
        d = inst[qid]
        if not d["persist"]:
            out.append(f"V6 · {qid}: the instruction carries no `**Persist:**` line"); continue
        under = lambda k, p: k == p or k.startswith(p + ".")
        for k in d["keys"]:
            if not any(under(r, k) for r in qkeys):
                out.append(f"V6 · {qid}: the instruction persists `{k}`, the registry question does not")
        for w in d["wild"]:
            if not any(r.startswith(w + ".") for r in qkeys):
                out.append(f"V6 · {qid}: the instruction persists `{w}.*`, the registry question has no key under it")
        for r in qkeys:
            if not any(under(r, k) for k in d["keys"] + d["wild"]):
                out.append(f"V6 · {qid}: the registry persists `{r}`, the instruction's `**Persist:**` line does not")
        if d["toks"] != len(d["keys"]) + len(d["wild"]):
            continue   # values named beside the keys: a mapping, not one key's literals
        okeys = [k for k in qkeys if any(x in (q["keys"][k] or {}) for x in ("options", "options_by"))]
        if d["options"] is None and d["rows"] is None:
            continue   # options written as prose or bullets: nothing literal to compare
        if len(okeys) != 1:
            if len(qkeys) == 1:
                out.append(f"V6 · {qid}: the instruction offers literals, the registry declares `{qkeys[0]}` free")
            continue
        spec = q["keys"][okeys[0]]
        if d["rows"] is not None and isinstance(spec.get("options_by"), dict):
            vals = spec["options_by"].get("values") or {}
            for lab in sorted(set(d["rows"]) | set(vals)):
                want = sorted({canon(x) for x in vals.get(lab, [])})
                if d["rows"].get(lab) != want:
                    out.append(f"V6 · {qid}: when `{lab}`, the instruction offers {' | '.join(d['rows'].get(lab, [])) or 'nothing'}; the registry {' | '.join(want) or 'nothing'}")
            continue
        have = d["options"] if d["options"] is not None else sorted({x for v in d["rows"].values() for x in v})
        reg_opts = _offered(spec) or []
        if have != reg_opts:
            out.append(f"V6 · {qid}: the instruction offers {' | '.join(have)}; the registry `{okeys[0]}` offers {' | '.join(reg_opts)}")
    ids = {q.get("id") for q in _questions(reg)}
    out += [f"V6 · the instruction's `#### {h}` has no registry question" for h in inst if h not in ids]
    return out


def _v7(repo: Path, reg: dict) -> list[str]:
    p = repo / TEMPLATE
    if not p.is_file():
        return [f"V7 · the setup template {TEMPLATE} is absent — the answer home has no slots"]
    slots = {k for k in flatten(read_frontmatter(p)) if k.split(".", 1)[0] not in NON_ANSWER_SLOTS}
    known = set(_specs(reg)) | set(_derived(reg))
    under = lambda a, b: a == b or a.startswith(b + ".")
    out = [f"V7 · `{k}` has no slot in the setup template frontmatter" for k in sorted(known) if not any(under(s, k) for s in slots)]
    out += [f"V7 · template slot `{s}` is not a registry or derived key (the non-answer slots are {', '.join(NON_ANSWER_SLOTS)})"
            for s in sorted(slots) if not any(under(s, k) for k in known)]
    return out


def _v9(reg: dict) -> list[str]:
    from . import corpus
    specs = _specs(reg)
    return [f"V9 · snapshot key `{k}` (corpus.STACK_KEYS) is not a registry key" for k in corpus.STACK_KEYS if k not in specs]


# ─── V8 · the consumer literals (ported from test-discovery-literals.sh, #143) ───

def _opts(reg: dict) -> dict:
    """The offered literals per key, and per question id when the question has one closed key."""
    out = {}
    for q in _questions(reg):
        closed = []
        for k, s in (q.get("keys") or {}).items():
            o = _offered(s) if isinstance(s, dict) else None
            if o is not None:
                out[k] = o; closed.append(k)
        if len(closed) == 1 and q.get("id"):
            out[q["id"]] = out[closed[0]]
    return out


def _v8(repo: Path, reg: dict, manifest: dict) -> list[str]:
    opts = _opts(reg)
    out = []

    def read(label, rel):
        p = repo / rel
        try:
            return p.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            out.append(f"V8 · {label}: {rel} is absent — nothing compared")
            return None

    def add(label, findings):
        out.extend(f"V8 · {label}: {f}" for f in findings[:12])

    entries = [(k, e) for _, sect in manifest.items() if isinstance(sect, dict) for k, e in sect.items() if isinstance(e, dict)]
    files = tracked_files(repo)

    # 1 · a literal compared in prose is offered
    lab = "conditional literals"
    cmp_ = re.compile(r"`?\b(Q\d+(?:\.\d+)?[a-z]?|[a-z_]+(?:\.[a-z_]+)+)`?\s*(==|!=)\s*"
                      r"(?:\"([^\"]+)\"|`([^`]+)`|'([^']+)'|((?!(?:AND|OR)\b)[\w.#+/-]+))")
    found = []
    for rel in files:
        if not rel.startswith((".claude/", ".context/templates/")) or "CHANGELOG" in rel or rel == REGISTRY \
                or any(fnmatch.fnmatch(rel, g) for g in NOT_CONSUMER_GLOBS):   # a test or a changelog is not a consumer
            continue
        try:
            text = (repo / rel).read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        for n, line in enumerate(text.splitlines(), 1):
            for m in cmp_.finditer(line):
                k, val = m.group(1), next(g for g in m.groups()[2:] if g is not None)
                if k in opts and val not in opts[k] + ["None", "null"]:
                    found.append(f"{rel}:{n}: `{k} {m.group(2)} {val}` — `{val}` is not offered ({' | '.join(opts[k])})")
    add(lab, found)

    # 2 · CI slugs: the materialisation's platform table names Q21's literals
    lab, q21 = "CI platform table", opts.get("ci_cd.platform", [])
    mat = read(lab, MATERIALIZATION)
    if mat is not None:
        rows = re.findall(r"^\| `([^`]+)` \| `(?:governance-check|inventory-drift)\.", mat, re.M)
        add(lab, [f"materialisation: `{r}` — not a ci_cd.platform literal ({' | '.join(q21)})" for r in rows if r not in q21]
            or ([] if rows else ["materialisation: no governance-check platform table found"]))

    # 3 · a platform-specific workflow carries its platform's conditional
    by_slug, found = {}, []
    for k, e in entries:
        m = re.fullmatch(r"workflows/[\w-]+\.([a-z-]+)\.(?:ya?ml|groovy)", k)
        if not m:
            continue
        lit = re.search(r'ci_cd\.platform == "([^"]+)"', e.get("stack_conditional") or "")
        if not lit:
            found.append(f"manifest {k}: a `{m.group(1)}` workflow with no `ci_cd.platform == \"…\"` conditional — it lands on every platform")
        else:
            by_slug.setdefault(m.group(1), set()).add(lit.group(1))
    found += [f"workflows `*.{s}.*` gate on different platforms: {sorted(v)}" for s, v in by_slug.items() if len(v) > 1]
    add("platform workflows", found)

    # 4 · every ci_cd.platform option has its pipeline templates
    conds = [(k, e.get("stack_conditional") or "") for k, e in entries]
    found = [] if q21 else ["the registry offers no ci_cd.platform options"]
    for lit in q21:
        if lit == "None":
            continue
        for kind in ("governance-check", "auto-tag"):
            if not any(k.startswith(f"workflows/{kind}.") and f'"{lit}"' in c for k, c in conds):
                found.append(f"ci_cd.platform offers `{lit}`; no `workflows/{kind}.*` template materialises for it")
    add("pipeline templates", found)

    # 5 · host enum: cloud_provider accepts every hosting.provider option
    lab = "host enum"
    cicd = read(lab, ".context/templates/setup/rules/ci-cd.md")
    if cicd is not None:
        m = re.search(r"cloud_provider: \{\{CLOUD_PROVIDER\}\}\s*#\s*(.+)$", cicd, re.M)
        enum = [x.strip() for x in m.group(1).split("|")] if m else []
        hp = opts.get("hosting.provider", [])
        add(lab, [f"hosting.provider offers `{o}`; rules/ci-cd.md cloud_provider accepts {enum}" for o in hp if o not in enum]
            or ([] if hp else ["the registry offers no hosting.provider options"]))

    # 6 · schema: every resource type the phases compare is in the registry schema
    lab = "infrastructure schema"
    raw = read(lab, ".context/schemas/infrastructure_registry.schema.json")
    if raw is not None:
        def enum_of(node):
            if isinstance(node, dict):
                if isinstance(node.get("type"), dict) and "enum" in node["type"]:
                    return node["type"]["enum"]
                for v in node.values():
                    r = enum_of(v)
                    if r:
                        return r
            return None
        try:
            types = enum_of(json.loads(raw)) or []
        except ValueError:
            types = []
        used = set()
        for rel in files:
            if rel.startswith((".claude/instructions/", ".claude/skills/")):
                try:
                    used.update(re.findall(r"resource\.type == \"([a-z_-]+)\"", (repo / rel).read_text(encoding="utf-8")))
                except (OSError, UnicodeDecodeError):
                    pass
        add(lab, [f"`{t}` used, the schema enum is {types}" for t in sorted(used) if t not in types]
            or ([] if types else ["no resource type enum in the schema"]))

    # 7 · DEVOPS topology labels as Q7 defines them (the codes' names are wording: the instruction holds them)
    lab = "DEVOPS topology"
    disc, dep = read(lab, INSTRUCTION), read(lab, ".claude/instructions/Factory-devops-provision-deploy.instructions.md")
    if disc is not None and dep is not None:
        q7 = dict(re.findall(r"\b(B\d+) \(([^,)]+), \$", disc))
        blk = re.search(r"Per architecture topology[^\n]*\n((?:[ \t]+.*\n)+?)\s*\n", dep)
        found, seen = [], []
        if not blk:
            found.append("Factory-devops-provision-deploy: no `Per architecture topology` block")
        else:
            for code, name in re.findall(r"\b(B\d+) ([^,:]+?)(?=,|:)", blk.group(1)):
                seen.append(code)
                if q7.get(code) != name.strip():
                    found.append(f"DEVOPS labels `{code} {name.strip()}`; Q7 defines `{code} {q7.get(code)}`")
            found += [f"{c} ({q7[c]}) — no build rule" for c in q7 if c not in seen]
            found += [f"{c} — more than one build rule" for c in sorted(set(seen)) if seen.count(c) > 1]
        add(lab, found)

    # 8 · lint-format discovers the rule files as they are named
    lab = "lint-format"
    lf = read(lab, ".context/templates/setup/scripts/lint-format.sh")
    if lf is not None:
        pat = re.search(r"find \.claude/rules [^\n]*-name '([^']+)'", lf)
        rules = [Path(e["target"]).name for _, e in entries if str(e.get("target", "")).startswith(".claude/rules/")]
        add(lab, [] if pat and any(fnmatch.fnmatch(r, pat.group(1)) for r in rules) else
            [f"lint-format.sh searches `.claude/rules` for `{pat.group(1) if pat else '?'}`; the rules land as {sorted(rules)[:4]}…"])

    # 9 · migration layouts the validator scans
    lab = "validate-migrations"
    vm = read(lab, ".context/templates/setup/scripts/validate-migrations.sh")
    if vm is not None:
        add(lab, [f"validate-migrations.sh does not scan {w}" for w in ('--include="*.php"', '"supabase/migrations"', '"drizzle/migrations"') if w not in vm])

    # 10 · one definition: the milestone literals, the upgrade checksum algorithm
    lab = "one definition"
    bo, usp = read(lab, ".claude/instructions/Factory-backlog-operations.instructions.md"), read(lab, ".context/templates/setup/upgrade_safety_protocol.md")
    found = []
    if bo is not None:
        ms = re.search(r"milestone_strategy: \"\{\{milestone_strategy\}\}\"\s*# Q27\.3: (.+)$", bo, re.M)
        lits = sorted(x.strip() for x in ms.group(1).split("|")) if ms else []
        if lits != opts.get("project_tracking.milestone_strategy"):
            found.append(f"backlog adapter milestone_strategy lists {lits}; the registry offers {opts.get('project_tracking.milestone_strategy')}")
    if usp is not None:
        algos = {a for a, p in (("MD5", r"\bMD5\b"), ("SHA-256", r"\bSHA-?256")) if re.search(p, usp, re.I)}
        if len(algos) != 1:
            found.append(f"upgrade_safety_protocol.md names {sorted(algos) or 'no'} checksum algorithm(s) for one checksum")
    add(lab, found)

    # 11 · the verification loop's rows name offered literals
    lab = "verification loop"
    bvl = read(lab, ".claude/skills/factory-build-verification/SKILL.md")
    if bvl is not None:
        found = []
        for k in ("backend.runtime", "frontend.framework"):
            blocks = [m.group(1) for m in re.finditer(r"MATCH stack\." + re.escape(k) + r":\n(([ \t]+)(?:\"|DEFAULT).*\n(?:\2[ \t]*\S.*\n)*)", bvl)]
            if not blocks or not opts.get(k):
                found.append(f"BVL: no `MATCH stack.{k}` block, or no {k} options in the registry — nothing compared")
            for blk in blocks:
                indent = re.match(r"[ \t]*", blk).group(0)
                for row in re.findall(r"^" + indent + r"(\"[^→]+?)\s*→", blk, re.M):
                    found += [f"BVL `MATCH stack.{k}` row `{lit}` — not offered ({' | '.join(opts.get(k, []))})"
                              for lit in re.findall(r"\"([^\"]+)\"", row) if lit not in opts.get(k, [])]
        add(lab, sorted(set(found)))

    # 12 · every offered stack literal has a dependency reader (#114, QA-PRE-1)
    from . import dependencies
    have, found = dependencies.readers(), []
    for k in ("backend.runtime", "frontend.framework"):
        found += [] if opts.get(k) else [f"the registry offers no {k} options — nothing compared"]
        found += [f"{k} `{lit}` is offered and has no dependency reader" for lit in opts.get(k, [])
                  if not lit.startswith("None") and lit not in have.get(k, [])]
    add("dependency readers", found)
    return out


def validate(repo: Path) -> list[str]:
    """Every finding of V1–V9, each prefixed by its rule. GateFault when the registry or the manifest cannot be read."""
    reg = load_registry(repo)
    manifest = load_manifest(repo)
    fw = _semver(manifest.get("framework_version"))
    out = _v1(reg, fw)
    if fw is None:
        out.append(f"V1 · framework_version `{manifest.get('framework_version')}` in {MANIFEST} is not x.y.z — `since` cannot be held to it")
    return out + _v2(reg) + _v3(reg) + _v4(repo, reg) + _v5(repo, reg, manifest) + _v6(repo, reg) + _v7(repo, reg) + _v8(repo, reg, manifest) + _v9(reg)


def render(findings: list[str]) -> str:
    if not findings:
        return "discovery: ok — the registry, its conditions, the instruction, the template and the consumers agree"
    return "\n".join([f"  ❌ {f}" for f in findings] + [f"discovery: RED — {len(findings)} finding(s)"])
